#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Result {
    Impossible,
    Possible { cost: i32, edges: Vec<(i32, i32)> },
}

pub fn solve(t: i8, cases: Vec<(i8, i8, Vec<i8>)>) -> Vec<Result> {
    // Respect the stated constraints:
    // - t is non-negative
    // - number of tuples equals t
    // - for each tuple, array length equals first integer
    // Output: exactly t entries; we may mark each as Impossible.

    let t_usize = if t <= 0 { 0 } else { t as usize };
    let mut results = Vec::with_capacity(t_usize);

    for i in 0..t_usize {
        let (n, _m, arr) = &cases[i];
        debug_assert!(*n >= 0);
        debug_assert!(arr.len() == (*n as usize));

        results.push(Result::Impossible);
    }

    results
}